
.status-card {
  width: 100%;
  max-width: 720px;
  background: var(--c-bg-deep);
  border: 1px solid var(--c-border);
  border-radius: 6px;
  display: flex;
  flex-direction: column;
  font-family: var(--font-sans);
  color: var(--c-text-primary);
  font-size: 13px;
  line-height: 1.5;
  margin: 0 auto;
  overflow: hidden;
  box-shadow:
    0 4px 24px rgba(0, 0, 0, 0.4),
    0 0 1px var(--c-border-glow);
}

/* 顶部装饰 */
.header-strip {
  position: relative;
  background: var(--c-bg-card);
  padding: 10px 0 0;
  overflow: hidden;
}

.scanline-overlay {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 2px,
    rgba(0, 229, 255, 0.015) 2px,
    rgba(0, 229, 255, 0.015) 4px
  );
  pointer-events: none;
}

.header-content {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 0 16px 8px;
}

.header-icon {
  color: var(--c-cyan);
  font-size: 0.7rem;
  opacity: 0.6;
}

.header-title {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  letter-spacing: 0.3em;
  color: var(--c-cyan);
  text-shadow: 0 0 10px rgba(0, 229, 255, 0.4);
  text-transform: uppercase;
}

.header-line {
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--c-cyan), transparent);
  opacity: 0.3;
}

/* 内容区域 */
.content-area {
  padding: 12px;
  min-height: 0;
  background: var(--c-bg-deep);
}

/* 过渡动画 */
.fade-enter-active,
.fade-leave-active {
  transition: all 0.25s ease;
}

.fade-enter-from,
.fade-leave-to {
  opacity: 0;
  transform: translateY(4px);
}

/* 底部装饰 */
.footer-strip {
  padding: 6px 16px;
  text-align: center;
  background: var(--c-bg-card);
  border-top: 1px solid var(--c-border);
}

.footer-text {
  font-family: var(--font-mono);
  font-size: 0.55rem;
  letter-spacing: 0.2em;
  color: var(--c-text-muted);
  text-transform: uppercase;
}
